import{_ as t,o as a,c as s,a4 as l}from"./chunks/framework.BUqnS5H7.js";const b=JSON.parse('{"title":"Classic Queue","description":"","frontmatter":{},"headers":[],"relativePath":"rabbitmq/03-queue/chapter-02-classic-queue.md","filePath":"rabbitmq/03-queue/chapter-02-classic-queue.md"}'),i={name:"rabbitmq/03-queue/chapter-02-classic-queue.md"};function c(u,e,n,r,d,p){return a(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="classic-queue" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">Classic Queue <a class="header-anchor" href="#classic-queue" aria-label="Permalink to &quot;Classic Queue&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><p data-src-line="3" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">Classic Queue 是 RabbitMQ 最早的队列类型。理解它是理解 Quorum Queue 的基础。</p></blockquote><h2 id="_1-classic-queue-的存储结构" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">1. Classic Queue 的存储结构 <a class="header-anchor" href="#_1-classic-queue-的存储结构" aria-label="Permalink to &quot;1. Classic Queue 的存储结构&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>│            Classic Queue                 │</span></span>
<span class="line"><span>│                                          │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Q1 (内存，未确认)                   │ │</span></span>
<span class="line"><span>│  │  [msg1][msg2][msg3]                 │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘ │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Q2 (内存引用，指向磁盘)             │ │</span></span>
<span class="line"><span>│  │  [ref1][ref2][ref3]                 │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘ │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Delta (磁盘，未读)                  │ │</span></span>
<span class="line"><span>│  │  [msg4][msg5][msg6]...              │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘ │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Q3 (磁盘索引)                       │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘ │</span></span>
<span class="line"><span>└──────────────────────────────────────────┘</span></span></code></pre></div><p data-src-line="29" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">Classic Queue 使用一种混合存储：热数据在内存（Q1），冷数据在磁盘（Delta），中间有索引（Q2/Q3）。</p><h2 id="_2-消息流转" tabindex="-1" data-src-line="31" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">2. 消息流转 <a class="header-anchor" href="#_2-消息流转" aria-label="Permalink to &quot;2. 消息流转&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>消息进入 → Q1（内存）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 内存够 → 一直在 Q1，直接消费</span></span>
<span class="line"><span>  └─ 内存不够 → 换页到磁盘（Delta），Q2 存引用</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>消费时：</span></span>
<span class="line"><span>  Q1 有消息 → 直接从 Q1 取</span></span>
<span class="line"><span>  Q1 空了 → 从 Delta 读磁盘 → 加载到 Q1</span></span></code></pre></div><h2 id="_3-classic-queue-的局限" tabindex="-1" data-src-line="44" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">3. Classic Queue 的局限 <a class="header-anchor" href="#_3-classic-queue-的局限" aria-label="Permalink to &quot;3. Classic Queue 的局限&quot;">​</a></h2><table tabindex="0"><thead data-src-line="46" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="46" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="48" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="48" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">镜像队列已废弃</td><td style="text-align:left;">3.x 版本中，Mirrored Queue 被 Quorum Queue 取代</td></tr><tr data-src-line="49" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">内存瓶颈</td><td style="text-align:left;">消息堆积时换页到磁盘，消费性能下降</td></tr><tr data-src-line="50" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">不支持流控回压</td><td style="text-align:left;">生产速度远大于消费速度时，可能撑爆内存</td></tr><tr data-src-line="51" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">故障恢复慢</td><td style="text-align:left;">Broker 崩溃后需要从磁盘重建索引</td></tr></tbody></table><h2 id="_4-classic-queue-参数" tabindex="-1" data-src-line="53" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">4. Classic Queue 参数 <a class="header-anchor" href="#_4-classic-queue-参数" aria-label="Permalink to &quot;4. Classic Queue 参数&quot;">​</a></h2><table tabindex="0"><thead data-src-line="55" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="55" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="57" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="57" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-max-length</td><td style="text-align:left;">不限</td><td style="text-align:left;">Queue 最大消息数</td></tr><tr data-src-line="58" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-max-length-bytes</td><td style="text-align:left;">不限</td><td style="text-align:left;">Queue 最大字节数</td></tr><tr data-src-line="59" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-overflow</td><td style="text-align:left;">drop-head</td><td style="text-align:left;">超限时行为：drop-head（丢最老）/ reject-publish</td></tr><tr data-src-line="60" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-message-ttl</td><td style="text-align:left;">不限</td><td style="text-align:left;">消息 TTL（毫秒）</td></tr><tr data-src-line="61" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-expires</td><td style="text-align:left;">不限</td><td style="text-align:left;">Queue 空闲超时自动删除</td></tr><tr data-src-line="62" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-max-priority</td><td style="text-align:left;">0</td><td style="text-align:left;">最大优先级（0=不启用）</td></tr><tr data-src-line="63" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-dead-letter-exchange</td><td style="text-align:left;">无</td><td style="text-align:left;">死信 Exchange</td></tr><tr data-src-line="64" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">x-dead-letter-routing-key</td><td style="text-align:left;">原 key</td><td style="text-align:left;">死信 routing key</td></tr></tbody></table><h2 id="_5-什么时候还用-classic-queue" tabindex="-1" data-src-line="66" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">5. 什么时候还用 Classic Queue <a class="header-anchor" href="#_5-什么时候还用-classic-queue" aria-label="Permalink to &quot;5. 什么时候还用 Classic Queue&quot;">​</a></h2><ul data-src-line="68" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><li data-src-line="68" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">已有系统在用 Classic Queue，且运行稳定</li><li data-src-line="69" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">不需要高可用（单节点场景）</li><li data-src-line="70" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">临时队列（排他、自动删除）</li><li data-src-line="71" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">需要优先级队列（Classic Queue 原生支持 x-max-priority）</li></ul><p data-src-line="73" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><strong>新项目建议直接用 Quorum Queue。</strong></p><h2 id="_6-classic-queue-vs-quorum-queue" tabindex="-1" data-src-line="75" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md">6. Classic Queue vs Quorum Queue <a class="header-anchor" href="#_6-classic-queue-vs-quorum-queue" aria-label="Permalink to &quot;6. Classic Queue vs Quorum Queue&quot;">​</a></h2><table tabindex="0"><thead data-src-line="77" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="77" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Classic Queue</th><th style="text-align:left;">Quorum Queue</th></tr></thead><tbody data-src-line="79" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><tr data-src-line="79" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">高可用</td><td style="text-align:left;">镜像队列（已废弃）</td><td style="text-align:left;">Raft 协议（内置）</td></tr><tr data-src-line="80" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">持久性</td><td style="text-align:left;">可选</td><td style="text-align:left;">强持久</td></tr><tr data-src-line="81" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">性能</td><td style="text-align:left;">更高（无共识开销）</td><td style="text-align:left;">稍低（Raft 共识）</td></tr><tr data-src-line="82" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">消息丢失风险</td><td style="text-align:left;">有（镜像异步复制）</td><td style="text-align:left;">极低（多数确认）</td></tr><tr data-src-line="83" data-src-file="rabbitmq/03-queue/chapter-02-classic-queue.md"><td style="text-align:left;">适用场景</td><td style="text-align:left;">临时队列、低可靠需求</td><td style="text-align:left;">生产环境、高可靠需求</td></tr></tbody></table>`,16)])])}const h=t(i,[["render",c]]);export{b as __pageData,h as default};
